<x-workspace :title="__('Appointment #:id', ['id'=>$appointment->id])" subtitle="{{ __('Everything you need to know about your visit.') }}"><section><x-badge :status="$appointment->status"/><dl><dt>{{ __('Dentist') }}</dt><dd>{{ $appointment->doctor_appointment_type->doctor_profile->user->name }}</dd><dt>{{ __('Service') }}</dt><dd>{{ $appointment->doctor_appointment_type->appointment_type->name }}</dd><dt>{{ __('Time') }}</dt><dd>{{ $appointment->scheduled_at->locale(app()->getLocale())->translatedFormat('l, d F Y · H:i') }} ({{ config('app.timezone') }})</dd><dt>{{ __('Reason') }}</dt><dd>{{ $appointment->reason ?: __('Not provided') }}</dd><dt>{{ __('Requested') }}</dt><dd>{{ $appointment->created_at->locale(app()->getLocale())->translatedFormat('d M Y · H:i') }}</dd></dl><a class="button" href="{{ route('patient.workspace') }}">{{ __('Manage appointments') }}</a></section></x-workspace>
